def is_simple_power(x, n):
    """Returns True if x is a simple power of n (i.e., x = n ** int), otherwise False."""
    if n == 1:
        return x == 1
    if x < 1:
        return False
    # Check if x is a power of n
    while x % n == 0:
        x //= n
    return x == 1
