def valid_date(date):
    """Validate a date string based on specific rules."""
    # Check if the date is not empty
    if not date:
        return False

    # Check the format: mm-dd-yyyy
    if not (date.count('-') == 2 and len(date) == 10):
        return False

    # Split the date into parts
    month_str, day_str, year_str = date.split('-')

    # Check if month and day are integers
    if not (month_str.isdigit() and day_str.isdigit() and year_str.isdigit()):
        return False

    month = int(month_str)
    day = int(day_str)
    year = int(year_str)

    # Check if month is between 1 and 12
    if not (1 <= month <= 12):
        return False

    # Check day based on the month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        # Check for leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if not (1 <= day <= 29):
                return False
        else:
            if not (1 <= day <= 28):
                return False

    return True
